/* Linear — dark, dense, engineered calm. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #5e6ad2;
	--color-primary-foreground: #ffffff;
	--color-surface: #08090a;
	--color-surface-foreground: #f7f8f8;
	--color-surface-raised: #131416;
	--color-muted: #8a8f98;
	--color-accent: #26b5ce;
	--color-danger: #eb5757;
	--color-border: #26282d;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.5);
	--shadow-md: 0 4px 16px rgb(0 0 0 / 0.5);
	--shadow-lg: 0 16px 48px rgb(0 0 0 / 0.6);
}

/* Site Stencil — a construction-site board. Concrete ground, hazard yellow,
   and black stencil type. Utilitarian 2026: signage, not a poster.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #f0c400;
	--color-primary-foreground: #161616;
	--color-surface: #e8e6e1;
	--color-surface-foreground: #161616;
	--color-surface-raised: #f6f5f2;
	--color-muted: #4d4d4d;
	--color-accent: #161616;
	--color-danger: #c42020;
	--color-border: #161616;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 9999px;

	/* Depth is a second black rule, not a drop and not a bevel. */
	--shadow-sm: 0 0 0 1px #161616;
	--shadow-md: 0 0 0 2px #161616;
	--shadow-lg: 0 0 0 3px #161616;
	--shadow-focus: 0 0 0 2px #e8e6e1, 0 0 0 4px #161616;

	--hazard: repeating-linear-gradient(-45deg, #161616 0 10px, #f0c400 10px 20px);
	--duration-snap: 80ms;
}

/* Doodle Pop — lime × black sticker energy: thick ink borders, hard offset shadows,
 * polka-dot textures, coral/lavender/sky pastel pops. Original Vetta preset. */
@theme {
	--color-primary: #d6f437;
	--color-primary-foreground: #111111;
	--color-surface: #c8e93c;
	--color-surface-foreground: #111111;
	--color-surface-raised: #ffffff;
	--color-muted: #55584a;
	--color-accent: #f4794f;
	--color-danger: #ef3b5d;
	--color-border: #111111;
	--color-cream: #f2f0e6;
	--color-lavender: #b39df3;
	--color-sky: #8ed8e8;
	--color-ink: #111111;

	--radius-sm: 8px;
	--radius-md: 12px;
	--radius-lg: 16px;
	--radius-xl: 20px;
	--radius-2xl: 28px;

	--shadow-sm: 2px 2px 0 #111111;
	--shadow-md: 4px 4px 0 #111111;
	--shadow-lg: 7px 7px 0 #111111;
}

/* Pixel Pocket — a pocket inventory built on a visible pixel grid.
   Flat blocks, stepped corners, no bevels. 2026 pixel revival, not a 1995 desktop.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #ff6b4a;
	--color-primary-foreground: #1b1a2a;
	--color-surface: #1b1a2a;
	--color-surface-foreground: #f3f0e6;
	--color-surface-raised: #26243a;
	--color-muted: #b7b3c9;
	--color-accent: #7dffe1;
	--color-danger: #ff4d6a;
	--color-border: #f3f0e6;

	--color-pixel-coin: #ffd15c;
	--color-pixel-coin-foreground: #1b1a2a;
	--color-pixel-water: #6ec8ff;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 0px;

	/* Stepped, hard, and aligned to a 4px grid. Never a smooth blur. */
	--shadow-sm: 2px 2px 0 #07060f;
	--shadow-md: 4px 4px 0 #07060f;
	--shadow-lg: 6px 6px 0 #07060f;
	--shadow-focus: 0 0 0 2px #1b1a2a, 0 0 0 4px #7dffe1;

	--pixel: 4px;
	--duration-step: 60ms;
}

/* Stripe — polished fintech, blurple on airy blue-gray. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #635bff;
	--color-primary-foreground: #ffffff;
	--color-surface: #f6f9fc;
	--color-surface-foreground: #0a2540;
	--color-surface-raised: #ffffff;
	--color-muted: #425466;
	--color-accent: #00d4ff;
	--color-danger: #df1b41;
	--color-border: #e6ebf1;

	--radius-sm: 6px;
	--radius-md: 8px;
	--radius-lg: 12px;
	--radius-xl: 16px;
	--radius-2xl: 24px;

	--shadow-sm: 0 2px 5px -1px rgb(50 50 93 / 0.12), 0 1px 3px -1px rgb(0 0 0 / 0.15);
	--shadow-md: 0 6px 12px -2px rgb(50 50 93 / 0.2), 0 3px 7px -3px rgb(0 0 0 / 0.15);
	--shadow-lg: 0 13px 27px -5px rgb(50 50 93 / 0.25), 0 8px 16px -8px rgb(0 0 0 / 0.3);
}

/* Meridian — a transit catalog. Blue-black field, one cold meridian,
   a ruled graticule, magnitudes as hard squares.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #e6e9ec;
	--color-primary-foreground: #101418;
	--color-surface: #101418;
	--color-surface-foreground: #e6e9ec;
	--color-surface-raised: #1a2128;
	--color-muted: #a9b4bc;
	--color-accent: #9ec4d4;
	--color-danger: #e3a097;
	--color-border: #3c4852;

	--color-grid: rgb(230 233 236 / 0.16);
	--color-grid-strong: rgb(230 233 236 / 0.4);
	--color-plate: #0c1014;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 0px;

	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: none;
	--shadow-focus: 0 0 0 1px #101418, 0 0 0 2px #9ec4d4;

	--duration-still: 160ms;
}

/* Sumi Ink — a tea-room book. Rice paper, soy-black ink, one cinnabar seal.
   Wabi-sabi quiet, not a magazine and not a print shop.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #1c1b19;
	--color-primary-foreground: #f2eee6;
	--color-surface: #f2eee6;
	--color-surface-foreground: #1c1b19;
	--color-surface-raised: #faf8f3;
	--color-muted: #5f5b55;
	--color-accent: #c4372c;
	--color-danger: #8e1d16;
	--color-border: #1c1b19;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 2px;
	--radius-full: 9999px;

	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: none;
	--shadow-focus: 0 0 0 1px #f2eee6, 0 0 0 3px #c4372c;

	--duration-brush: 180ms;
}

/* Spotify — near-black stage, one electric green, pill everything. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #1db954;
	--color-primary-foreground: #000000;
	--color-surface: #121212;
	--color-surface-foreground: #ffffff;
	--color-surface-raised: #1f1f1f;
	--color-muted: #a7a7a7;
	--color-accent: #1ed760;
	--color-danger: #f15e6c;
	--color-border: #2a2a2a;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 2px 4px rgb(0 0 0 / 0.4);
	--shadow-md: 0 8px 24px rgb(0 0 0 / 0.5);
	--shadow-lg: 0 16px 56px rgb(0 0 0 / 0.7);
}

/* Late Edition — a city broadsheet. Warm newsprint, carbon ink,
   a tracked nameplate, three ruled columns. Structured editorial
   quiet, not a blog and not a gallery wall.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #1c1612;
	--color-primary-foreground: #f3eadc;
	--color-surface: #e4d8c6;
	--color-surface-foreground: #1c1612;
	--color-surface-raised: #f3eadc;
	--color-muted: #5e5348;
	--color-accent: #8a332c;
	--color-danger: #6e2c28;
	--color-border: #1c1612;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 0px;

	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: none;
	--shadow-focus: 0 0 0 1px #e4d8c6, 0 0 0 2px #8a332c;

	--duration-still: 140ms;
}

/* Meadow Buddies — soft woodland fitness. Original implementation; reference image excluded. */
@theme {
	--color-primary: #492724;
	--color-primary-foreground: #fffdf8;
	--color-surface: #f8f9f5;
	--color-surface-foreground: #2d2423;
	--color-surface-raised: #ffffff;
	--color-muted: #6f756a;
	--color-accent: #a5bf7d;
	--color-danger: #a45c40;
	--color-border: #e8ece5;
	--color-sage-light: #dce7bf;
	--color-sage-dark: #526b43;
	--color-apricot: #f9cc87;
	--color-apricot-light: #fff0d1;
	--color-honey: #da941b;
	--color-ochre: #856222;
	--color-mist: #f2f6f6;
	--color-stage-end: #cbd6cd;
	--color-stone: #89806d;
	--font-sans: "Avenir Next", "Trebuchet MS", Arial, sans-serif;
	--radius-sm: 8px;
	--radius-md: 16px;
	--radius-lg: 22px;
	--radius-xl: 34px;
	--radius-2xl: 44px;
	--shadow-sm: 0 3px 8px rgb(65 82 46 / 0.04);
	--shadow-md: 0 10px 24px rgb(65 82 46 / 0.06);
	--shadow-lg: 0 28px 44px -18px rgb(65 82 46 / 0.22);
}

/* Notion — quiet warm-gray writing surface, ink first. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #2383e2;
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff;
	--color-surface-foreground: #37352f;
	--color-surface-raised: #f7f6f3;
	--color-muted: #787774;
	--color-accent: #d9730d;
	--color-danger: #eb5757;
	--color-border: #e9e9e7;

	--radius-sm: 3px;
	--radius-md: 4px;
	--radius-lg: 6px;
	--radius-xl: 8px;
	--radius-2xl: 12px;

	--shadow-sm: 0 1px 2px rgb(15 15 15 / 0.06);
	--shadow-md: 0 2px 6px rgb(15 15 15 / 0.08), 0 0 0 1px rgb(15 15 15 / 0.03);
	--shadow-lg: 0 8px 24px rgb(15 15 15 / 0.12), 0 0 0 1px rgb(15 15 15 / 0.04);
}

/* Lamp Room — a night library. Oxblood dark, candle amber, book-spine dyes.
   Dark academia as a hold desk, not a cream literary homepage.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #e07a3d;
	--color-primary-foreground: #1a1210;
	--color-surface: #1a1210;
	--color-surface-foreground: #f3e6d4;
	--color-surface-raised: #261a16;
	--color-muted: #c4b09a;
	--color-accent: #e6c27a;
	--color-danger: #e15a4a;
	--color-border: #6b4a38;

	--color-spine-wine: #6e2430;
	--color-spine-forest: #24362c;
	--color-spine-navy: #1c3048;

	--radius-sm: 2px;
	--radius-md: 2px;
	--radius-lg: 3px;
	--radius-xl: 4px;
	--radius-2xl: 4px;
	--radius-full: 9999px;

	--shadow-sm: 0 6px 16px rgb(0 0 0 / 0.35);
	--shadow-md: 0 12px 28px rgb(0 0 0 / 0.45);
	--shadow-lg: 0 20px 40px rgb(0 0 0 / 0.55);
	--shadow-focus: 0 0 0 2px #1a1210, 0 0 0 4px #e6c27a;

	--duration-lamp: 160ms;
}

/* Vercel — stark black-on-white monochrome, one blue. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #000000;
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff;
	--color-surface-foreground: #000000;
	--color-surface-raised: #fafafa;
	--color-muted: #666666;
	--color-accent: #0070f3;
	--color-danger: #ee0000;
	--color-border: #eaeaea;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.06);
	--shadow-md: 0 4px 12px rgb(0 0 0 / 0.08);
	--shadow-lg: 0 12px 32px rgb(0 0 0 / 0.12);
}

/* Cyanotype — a drawing sheet. Prussian blue ground, white linework,
   a title block. Sun-print chemistry, not a dark developer theme.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #f5f8fc;
	--color-primary-foreground: #0c3d7a;
	--color-surface: #0c3d7a;
	--color-surface-foreground: #f5f8fc;
	--color-surface-raised: #0a3268;
	--color-muted: #c9daf0;
	--color-accent: #8ecbff;
	--color-danger: #ffb1a3;
	--color-border: #d7e7f8;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 9999px;

	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: none;
	--shadow-focus: 0 0 0 1px #0c3d7a, 0 0 0 2px #f5f8fc;

	--grid-line: rgb(215 231 248 / 0.28);
	--duration-draw: 120ms;
}

/* Headspace — warm sunrise calm, rounded everything, friendly ink. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #f47d31;
	--color-primary-foreground: #ffffff;
	--color-surface: #fefaf3;
	--color-surface-foreground: #2d2c41;
	--color-surface-raised: #ffffff;
	--color-muted: #7a7889;
	--color-accent: #5a77d6;
	--color-danger: #e5484d;
	--color-border: #efe4d5;

	--radius-sm: 10px;
	--radius-md: 14px;
	--radius-lg: 18px;
	--radius-xl: 24px;
	--radius-2xl: 32px;

	--shadow-sm: 0 2px 6px rgb(45 44 65 / 0.06);
	--shadow-md: 0 8px 20px rgb(45 44 65 / 0.08);
	--shadow-lg: 0 20px 48px rgb(45 44 65 / 0.12);
}

/* First Frame — a title held in the gate. Warm black, ivory serif,
   fine grain, credits that fill the frame. A paused picture,
   not a streaming shelf and not a supper club.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #f3ecdf;
	--color-primary-foreground: #14110e;
	--color-surface: #14110e;
	--color-surface-foreground: #f3ecdf;
	--color-surface-raised: #211c18;
	--color-muted: #b3a89c;
	--color-accent: #c65b3e;
	--color-danger: #e7b6a4;
	--color-border: #4a433c;
	--color-bar: #090807;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 0px;

	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: none;
	--shadow-focus: 0 0 0 1px #14110e, 0 0 0 2px #c65b3e;

	--duration-still: 160ms;
}

/* Wax Coat — a materials-index plate. Cool paper, mineral tooth,
   one matte wax coat. Original system authored by Grok Bot. */
@theme {
	--color-primary: #1c1b19;
	--color-primary-foreground: #f4f1eb;
	--color-surface: #e6e7e4;
	--color-surface-foreground: #1c1b19;
	--color-surface-raised: #f4f2ec;
	--color-muted: #5c635e;
	--color-accent: #8a5340;
	--color-danger: #8e3830;
	--color-border: #c5cbc6;

	--color-plaster: #d2c4ae;
	--color-wax: #4e3228;
	--color-pit: #6a5344;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 0px;

	--shadow-sm: 0 8px 18px rgb(28 27 25 / 0.06);
	--shadow-md: 0 16px 32px rgb(28 27 25 / 0.08);
	--shadow-lg: 0 24px 40px rgb(28 27 25 / 0.1);
	--shadow-focus: 0 0 0 1px #e6e7e4, 0 0 0 3px #8a5340;

	--duration-still: 160ms;
}

/* GitHub — dark dimmed code habitat, green actions, blue links. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #238636;
	--color-primary-foreground: #ffffff;
	--color-surface: #0d1117;
	--color-surface-foreground: #e6edf3;
	--color-surface-raised: #161b22;
	--color-muted: #8b949e;
	--color-accent: #58a6ff;
	--color-danger: #f85149;
	--color-border: #30363d;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 6px;
	--radius-xl: 8px;
	--radius-2xl: 12px;

	--shadow-sm: 0 1px 0 rgb(1 4 9 / 0.6);
	--shadow-md: 0 3px 6px rgb(1 4 9 / 0.7);
	--shadow-lg: 0 8px 24px rgb(1 4 9 / 0.8);
}

/* Field Drawer — a specimen tray on khaki board. Eight material blocks,
   a depth ledger, no desert and no hazard stripe.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #1f1c16;
	--color-primary-foreground: #f3efe6;
	--color-surface: #cfc6b2;
	--color-surface-foreground: #1f1c16;
	--color-surface-raised: #e4dccb;
	--color-muted: #4e493f;
	--color-accent: #7a3f28;
	--color-danger: #7c302c;
	--color-border: #6a6254;

	--color-recess: #b7ad98;
	--color-chalk: #efe6d6;
	--color-bone: #e2d3bc;
	--color-sand: #d2bc94;
	--color-clay: #b07a48;
	--color-shale: #5e5952;
	--color-oxide: #6e3d2e;
	--color-slate: #3c4650;
	--color-char: #2a2826;

	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 0px;

	--shadow-sm: inset 0 1px 0 rgb(243 239 230 / 0.45);
	--shadow-md: inset 0 12px 28px rgb(31 28 22 / 0.16);
	--shadow-lg: 0 16px 28px rgb(31 28 22 / 0.12);
	--shadow-focus: 0 0 0 1px #cfc6b2, 0 0 0 3px #7a3f28;

	--duration-still: 160ms;
}

/* Geometric Bold — Bauhaus / constructivist poster. Pure primaries, no soft anything.
   Palette adapted from the StyleKit「几何大胆风」guide (see meta.json origin). */
@theme {
	--color-primary: #000000;
	--color-primary-foreground: #ffffff;
	--color-surface: #ffffff;
	--color-surface-foreground: #000000;
	--color-surface-raised: #ffffff;
	--color-muted: #6c3b00;
	--color-accent: #0000ff;
	--color-danger: #ff0000;
	--color-border: #000000;

	/* Shape palette — the four poster inks. Use as full blocks, never as tints. */
	--color-block-red: #ff0000;
	--color-block-blue: #0000ff;
	--color-block-yellow: #ffff00;
	--color-block-earth: #6c3b00;

	/* Foregrounds that stay legible on each block. */
	--color-block-red-foreground: #ffffff;
	--color-block-blue-foreground: #ffffff;
	--color-block-yellow-foreground: #000000;
	--color-block-earth-foreground: #ffffff;

	/* Two radii only: a shape is either a hard rectangle or a perfect circle. */
	--radius-sm: 0px;
	--radius-md: 0px;
	--radius-lg: 0px;
	--radius-xl: 0px;
	--radius-2xl: 0px;
	--radius-full: 9999px;

	/* Structure comes from 4px borders. Border widths, not elevation. */
	--border-width-hair: 2px;
	--border-width-base: 4px;
	--border-width-heavy: 8px;

	/* No blur, ever. Floating layers get a hard offset block so they still read
	   as "above" without introducing soft depth. */
	--shadow-sm: none;
	--shadow-md: none;
	--shadow-lg: 8px 8px 0 0 #000000;
}

/* Y3K Chrome — liquid metal in a void. Silver type, one iridescent orb,
   no glass blur. Hyperfuturism, not nocturne glazing.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #e8eef8;
	--color-primary-foreground: #101218;
	--color-surface: #07080d;
	--color-surface-foreground: #eef1f6;
	--color-surface-raised: #12131c;
	--color-muted: #a7b0c2;
	--color-accent: #7af0ff;
	--color-danger: #ff5c7a;
	--color-border: #2c3344;

	--color-iris: #d7a0ff;

	--radius-sm: 2px;
	--radius-md: 4px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;
	--radius-full: 9999px;

	--shadow-sm: 0 0 0 1px rgb(232 238 248 / 0.28);
	--shadow-md: 0 0 0 1px rgb(232 238 248 / 0.4), 0 10px 28px rgb(122 240 255 / 0.12);
	--shadow-lg: 0 0 0 1px rgb(232 238 248 / 0.5), 0 18px 40px rgb(215 160 255 / 0.16);
	--shadow-focus: 0 0 0 2px #07080d, 0 0 0 4px #7af0ff;

	--metal: linear-gradient(180deg, #ffffff 0%, #d5deea 38%, #8b97ab 50%, #f4f7fb 62%, #b7c3d6 100%);
	--duration-glide: 180ms;
}

/* Soft 3D — matte clay / vinyl volume on a peach-cream ground.
   One upper-left light, a broad highlight, lower-right occlusion, and a
   separate contact shadow. Not a hard offset extrusion, not glass, not gloss.
   Original system authored by Grok Bot. */
@theme {
	--color-primary: #2c2428;
	--color-primary-foreground: #fff8f3;
	--color-surface: #f6e6da;
	--color-surface-foreground: #3a2a32;
	--color-surface-raised: #fff8f3;
