	--mesh-night: radial-gradient(ellipse 130% 78% at 50% 108%, var(--color-glow-amber) 0%, var(--color-glow-amber) 18%, var(--color-glow-mauve) 46%, transparent 74%);

	--radius-sm: 12px;
